--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    first_name character varying(100) NOT NULL,
    last_name character varying(100) NOT NULL,
    email character varying(255) NOT NULL,
    mobile_number character varying(20),
    password_hash text NOT NULL,
    gender character varying(20),
    date_of_birth date,
    education text,
    class_level character varying(50),
    profile_image text,
    is_active boolean DEFAULT true,
    is_verified boolean DEFAULT false,
    last_login_at timestamp without time zone,
    active_role character varying(50) DEFAULT 'student'::character varying,
    created_at timestamp without time zone DEFAULT now(),
    updated_at timestamp without time zone DEFAULT now(),
    deleted_at timestamp without time zone,
    branch character varying(100),
    primary_organization_id uuid,
    unique_registration_id character varying(20) DEFAULT public.generate_registration_id()
);


--
-- Name: v_class_assignments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_class_assignments AS
 SELECT id AS assignment_id,
    classroom_id AS class_id,
    title,
    description,
    attachment_url,
    instructions,
    due_date,
    is_time_bound,
    created_at,
    updated_at
   FROM public.classroom_assignments ca;


--
-- Name: v_class_contents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_class_contents AS
 SELECT id AS link_id,
    classroom_id AS class_id,
    content_id,
    sort_order,
    created_at
   FROM public.classroom_contents cc;


--
-- Name: v_class_quizzes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_class_quizzes AS
 SELECT id AS link_id,
    classroom_id AS class_id,
    quiz_id,
    sort_order,
    created_at
   FROM public.classroom_quizzes cq;


--
-- Name: v_content_quiz; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_content_quiz AS
 SELECT lcs.content_id,
    lc.title AS content_title,
    lcs.id AS section_id,
    lcs.section_order,
    lcs.title AS section_title,
    lcs.quiz_id,
    q.title AS quiz_title,
    q.total_questions
   FROM ((public.learning_content_sections lcs
     JOIN public.learning_contents lc ON ((lc.id = lcs.content_id)))
     JOIN public.quizzes q ON ((q.id = lcs.quiz_id)))
  WHERE (lcs.quiz_id IS NOT NULL);


--
-- Name: v_content_sections; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_content_sections AS
 SELECT id AS section_id,
    content_id,
    section_order,
    title,
    content_type,
    media_url,
    external_url,
    text_content,
    quiz_id,
    created_at,
    updated_at
   FROM public.learning_content_sections lcs;


--
-- Name: v_contents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_contents AS
 SELECT lc.id AS content_id,
    lc.organization_id,
    lc.class_level,
    lc.subject_id,
    s.title AS subject_title,
    lc.title AS content_title,
    lc.content_type,
    lc.media_url,
    lc.external_url,
    lc.text_content,
    lc.is_global,
    lc.created_by,
    lc.created_at,
    lc.updated_at
   FROM (public.learning_contents lc
     LEFT JOIN public.subjects s ON ((s.id = lc.subject_id)));


--
-- Name: v_question_responses; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_question_responses AS
 SELECT id AS response_id,
    attempt_id,
    question_id,
    is_correct,
    response_data,
    time_spent_seconds
   FROM public.question_attempts qa;


--
-- Name: v_questions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_questions AS
 SELECT id AS question_id,
    quiz_id,
    question_type,
    question_title,
    question_instruction,
    question_audio,
    time_limit_seconds,
    points,
    sort_order,
    question_data,
    created_at
   FROM public.quiz_questions qq;


--
-- Name: v_quiz_attempts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_quiz_attempts AS
 SELECT sa.id AS attempt_id,
    sa.student_id,
    sa.quiz_id,
    q.title AS quiz_title,
    q.organization_id AS quiz_organization_id,
    sa.score,
    sa.total_points,
        CASE
            WHEN (sa.total_points > 0) THEN round((((sa.score)::numeric / (sa.total_points)::numeric) * (100)::numeric))
            ELSE (0)::numeric
        END AS score_pct,
    sa.completed_at,
    sa.idempotency_key
   FROM (public.student_attempts sa
     LEFT JOIN public.quizzes q ON ((q.id = sa.quiz_id)));


--
-- Name: v_quizzes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_quizzes AS
 SELECT q.id AS quiz_id,
    q.organization_id,
    q.class_level,
    q.subject_id,
    s.title AS subject_title,
    q.topic_id,
    t.title AS topic_title,
    q.title AS quiz_title,
    q.description,
    q.thumbnail_image,
    q.quiz_type,
    q.kind,
    q.difficulty_level,
    q.background_music_url,
    q.theme,
    q.total_questions,
    q.is_published,
    q.is_ai_generated,
    q.is_global,
    q.created_by,
    q.created_at,
    q.updated_at
   FROM ((public.quizzes q
     LEFT JOIN public.subjects s ON ((s.id = q.subject_id)))
     LEFT JOIN public.content_topics t ON ((t.id = q.topic_id)));


--
-- Name: v_student_class_assignment_submissions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_student_class_assignment_submissions AS
 SELECT id AS submission_id,
    classroom_assignment_id AS assignment_id,
    student_id,
    submission_text,
    attachment_url,
    submitted_at,
    updated_at
   FROM public.classroom_assignment_submissions cas;


--
-- Name: v_subjects; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_subjects AS
 SELECT id,
    organization_id,
    class_level,
    title,
    description,
    cover_image,
    icon_image,
    icon_bg_color,
    author,
    author_user_id,
    is_external_author,
    created_at,
    updated_at,
    COALESCE(( SELECT string_agg((sa.alias)::text, ', '::text ORDER BY (sa.alias)::text) AS string_agg
           FROM public.subject_aliases sa
          WHERE (sa.subject_id = s.id)), ''::text) AS aliases
   FROM public.subjects s;


--
-- Name: v_topic_contents; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_topic_contents AS
 SELECT id AS link_id,
    topic_id,
    content_id,
    sort_order,
    created_at
   FROM public.topic_content_assignments tca;


--
-- Name: v_topic_sections; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_topic_sections AS
 SELECT id AS section_id,
    topic_id,
    section_order,
    title,
    content_type,
    media_url,
    external_url,
    text_content,
    created_at,
    updated_at
   FROM public.topic_content_sections tcs;


--
-- Name: v_topics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_topics AS
 SELECT t.id AS topic_id,
    t.organization_id,
    t.class_level,
    t.subject_id,
    s.title AS subject_title,
    t.title AS topic_title,
    t.cover_image,
    t.is_global,
    t.created_by,
    t.created_at,
    t.updated_at
   FROM (public.content_topics t
     LEFT JOIN public.subjects s ON ((s.id = t.subject_id)));


